sub=[];nodes=['[node name="DormModularCandidate" type="Node2D"]\ntexture_filter = 1\nmetadata/status = "candidate_not_production"','[node name="CleanPlate" type="Sprite2D" parent="."]\ntexture = ExtResource("1")\ncentered = false','[node name="Furnishings" type="Node2D" parent="."]\nposition = Vector2(66, 65)\nscale = Vector2(0.9, 0.9)\ny_sort_enabled = true']
